// =============================================================
// AFRISUPPLY — Référentiel produits africains (partagé)
// ~300 références : nom canonique, alias (orthographes, langues,
// noms locaux), catégorie, unité de base, origine typique,
// conditionnements courants chez les grossistes, DLC moyenne,
// saisonnalité (mois de pleine saison, 1-12 ; vide = toute l'année).
// =============================================================

export type Cat = 'feculents' | 'frais' | 'viandes_poissons' | 'epicerie' | 'boissons' | 'emballages';
export type Unit = 'kg' | 'g' | 'L' | 'mL' | 'piece' | 'botte' | 'sac' | 'carton';

export interface RefProduct {
  name: string;
  category: Cat;
  baseUnit: Unit;
  aliases: string[];
  origin?: string;
  packs: string[];          // conditionnements usuels (ex: "Sac 25 kg")
  shelfLifeDays?: number;
  season?: number[];        // mois de pleine saison
  tags?: string[];          // usages / plats (aide la recherche et l'onboarding)
}

const P = (name: string, category: Cat, baseUnit: Unit, aliases: string[], packs: string[], origin?: string, shelfLifeDays?: number, tags: string[] = [], season?: number[]): RefProduct =>
  ({ name, category, baseUnit, aliases, packs, origin, shelfLifeDays, tags, season });

