/** Index de recherche : nom normalisé + alias + tags → produit. */
export const normalize = (s: string) =>
  s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[’']/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();

export function findReferenceProduct(query: string): RefProduct | undefined {
  const q = normalize(query);
  if (!q) return undefined;
  let exact = REFERENCE_PRODUCTS.find((p) => normalize(p.name) === q || p.aliases.some((a) => normalize(a) === q));
  if (exact) return exact;
  // nom contenu dans la requête ou requête contenue dans le nom / alias
  exact = REFERENCE_PRODUCTS.find((p) => normalize(p.name).includes(q) || p.aliases.some((a) => normalize(a).includes(q)));
  if (exact) return exact;
  return REFERENCE_PRODUCTS.find((p) => q.includes(normalize(p.name)) || p.aliases.some((a) => a.length > 3 && q.includes(normalize(a))));
}

